import{a as e,c as t,i as n,t as r}from"./app-B8uz0aqq.js";var i=JSON.parse(`{"path":"/26-Client_Resource_and_Patch.html","title":"客户端资源与补丁策略","lang":"en-US","frontmatter":{},"filePathRelative":"26-Client_Resource_and_Patch.md","git":{"createdTime":1765122408000,"updatedTime":1765122408000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`26-Client_Resource_and_Patch.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="客户端资源与补丁策略" tabindex="-1"><a class="header-anchor" href="#客户端资源与补丁策略"><span>客户端资源与补丁策略</span></a></h1><blockquote><p>目的：统一 Unity/U3D 客户端的资源打包、版本控制、热更新流程，使其与服务器的配置与灰度策略匹配，类似火龙果等产品提供的 SDK/资源方案。</p></blockquote><h2 id="_1-总体流程" tabindex="-1"><a class="header-anchor" href="#_1-总体流程"><span>1. 总体流程</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">资源制作 (美术/策划) → AssetBundle 构建 → 版本打包 → CDN/OSS 发布</span>
<span class="line">                      ↘ 差异包生成 → Patch Manifest → SDK 资源管理器</span>
<span class="line">客户端启动 → 检查 Manifest → 下载差异 → 校验 → 加载运行</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>服务器参与点：</p><ul><li>向 SDK 返回当前服要求的资源版本/灰度信息。</li><li>若版本不符，提示更新或强制下载。</li></ul><h2 id="_2-资源结构" tabindex="-1"><a class="header-anchor" href="#_2-资源结构"><span>2. 资源结构</span></a></h2><table><thead><tr><th>目录</th><th>内容</th></tr></thead><tbody><tr><td><code>assets/bundles</code></td><td>Unity AssetBundle、单元资源</td></tr><tr><td><code>assets/config</code></td><td>JSON/ScriptableObject 配置（与服务器配置对应）</td></tr><tr><td><code>assets/localization</code></td><td>语言包</td></tr><tr><td><code>patch/manifest.json</code></td><td>包含版本、依赖、大小、hash 的文件描述</td></tr><tr><td><code>patch/diffs/</code></td><td>差分包目录</td></tr></tbody></table><p>Manifest 示例：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;app_version&quot;</span><span class="token operator">:</span> <span class="token string">&quot;1.0.0&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;resource_version&quot;</span><span class="token operator">:</span> <span class="token string">&quot;2025.01.05&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;bundles&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">&quot;name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;characters.ab&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;hash&quot;</span><span class="token operator">:</span> <span class="token string">&quot;abcdef...&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;size&quot;</span><span class="token operator">:</span> <span class="token number">5242880</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;dependencies&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;animations.ab&quot;</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;priority&quot;</span><span class="token operator">:</span> <span class="token number">1</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">]</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-unity-sdk-资源管理" tabindex="-1"><a class="header-anchor" href="#_3-unity-sdk-资源管理"><span>3. Unity SDK 资源管理</span></a></h2><h3 id="_3-1-功能" tabindex="-1"><a class="header-anchor" href="#_3-1-功能"><span>3.1 功能</span></a></h3><ul><li>启动时获取服务器的资源版本（通过 API），对比本地 Manifest。</li><li>下载差分包或全量资源，支持断点续传、多线程。</li><li>校验 Hash，存储到本地缓存（Versioned folder）。</li><li>提供事件回调（进度、失败重试）。</li><li>支持灰度：根据 <code>slot</code>（来自服务器 NetCore 握手）选择不同资源版本。</li></ul><h3 id="_3-2-热更新流程" tabindex="-1"><a class="header-anchor" href="#_3-2-热更新流程"><span>3.2 热更新流程</span></a></h3><ol><li>客户端启动，加载内置 Manifest（与 APK 同步）。</li><li>调用服务器 API（或 CDN Manifest）获取最新版本。</li><li>若版本较新，下载差异文件（按优先级）并更新 Manifest。</li><li>对配置/脚本（如 Lua）可加载内存执行，资源（模型、UI）加载到 AssetBundle。</li></ol><h3 id="_3-3-安全" tabindex="-1"><a class="header-anchor" href="#_3-3-安全"><span>3.3 安全</span></a></h3><ul><li>下载使用 HTTPS；Manifest 签名/加密，防篡改。</li><li>客户端验证文件 Hash 与签名。</li><li>可启用文件加密（XOR/AES），配合 License 控制。</li></ul><h2 id="_4-cdn-发布策略" tabindex="-1"><a class="header-anchor" href="#_4-cdn-发布策略"><span>4. CDN/发布策略</span></a></h2><h3 id="_4-1-多环境" tabindex="-1"><a class="header-anchor" href="#_4-1-多环境"><span>4.1 多环境</span></a></h3><ul><li>Dev/Test/Staging/Prod 各自拥有独立资源仓库。</li><li>支持灰度/地区区分（例如 <code>cdn.com/prod/asia/</code>）。</li></ul><h3 id="_4-2-发布流程" tabindex="-1"><a class="header-anchor" href="#_4-2-发布流程"><span>4.2 发布流程</span></a></h3><ol><li>资源构建 → 上传 OSS（含版本号）。</li><li>生成 Manifest + 差分包（基于上一版本）。</li><li>触发 CDN 刷新（特定路径）。</li><li>更新版本数据库（供服务器/SDK 查询）。</li></ol><p>工具建议：Unity Addressables + 自研 Manifest；或结合第三方（AssetGraph）。</p><h2 id="_5-服务器接口" tabindex="-1"><a class="header-anchor" href="#_5-服务器接口"><span>5. 服务器接口</span></a></h2><h3 id="_5-1-资源版本-api" tabindex="-1"><a class="header-anchor" href="#_5-1-资源版本-api"><span>5.1 资源版本 API</span></a></h3><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line">GET /api/v1/resources/version?app=client&amp;platform=android&amp;slot=A</span>
<span class="line">Response:</span>
<span class="line">{</span>
<span class="line">  &quot;resource_version&quot;: &quot;2025.01.05&quot;,</span>
<span class="line">  &quot;manifest_url&quot;: &quot;https://cdn/.../manifest.json&quot;,</span>
<span class="line">  &quot;force_update&quot;: false,</span>
<span class="line">  &quot;message&quot;: &quot;Optional update&quot;</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>服务器根据玩家所属大区/灰度 slot 返回不同版本。</li><li><code>force_update=true</code> 时客户端必须更新后才能进入游戏。</li></ul><h3 id="_5-2-配置更新" tabindex="-1"><a class="header-anchor" href="#_5-2-配置更新"><span>5.2 配置更新</span></a></h3><ul><li>当服务器配置更新（<code>docs/02</code>）时，应同步生成客户端配置包，确保字段一致。</li><li>可使用相同 IDL/生成工具输出 JSON/Lua，避免手工同步。</li></ul><h2 id="_6-灰度与回滚" tabindex="-1"><a class="header-anchor" href="#_6-灰度与回滚"><span>6. 灰度与回滚</span></a></h2><ul><li>版本策略：<code>major.minor.patch</code> + 资源日期，如 <code>1.2.0+20250105</code>.</li><li>灰度发布： <ol><li>将 Manifest 标记为灰度版本，关联玩家 slot。</li><li>SDK 根据 slot 下载对应资源。</li><li>若监控正常，再将版本切换为全量。</li></ol></li><li>回滚：保留上一版本 Manifest + 资源包，切换 API 指向旧版本即可。</li></ul><h2 id="_7-监控与告警" tabindex="-1"><a class="header-anchor" href="#_7-监控与告警"><span>7. 监控与告警</span></a></h2><ul><li>指标：下载成功率、平均下载时间、失败次数、灰度覆盖率。</li><li>SDK 上传下载日志（带 trace_id），便于分析问题。</li><li>CDN/OSS 使用监控（QPS、带宽、错误率）。</li></ul><h2 id="_8-实施步骤" tabindex="-1"><a class="header-anchor" href="#_8-实施步骤"><span>8. 实施步骤</span></a></h2><ol><li>确定资源打包方案（Unity Addressables/自研）。</li><li>开发 Manifest 生成工具、差异包生成工具。</li><li>搭建 CDN/OSS 流程、版本数据库、发布脚本。</li><li>在 Unity SDK 中实现资源管理模块，支持热更新、灰度。</li><li>与服务器 API 接入，完成版本控制。</li><li>建立监控/日志系统，定期回顾。</li></ol><hr><p>通过该策略，客户端资源更新将与服务器配置/灰度机制同步，可高效、安全地向玩家发布新内容或修复补丁。***</p>`,37)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};